\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Color Theme (Dark navy + electric accents) ──
\definecolor{primary}{HTML}{0F172A}        % deep slate/navy
\definecolor{secondary}{HTML}{2563EB}      % electric blue
\definecolor{accent}{HTML}{10B981}         % vibrant green
\definecolor{accent2}{HTML}{F59E0B}        % warm amber
\definecolor{bgposter}{HTML}{0F172A}       % dark navy background
\definecolor{cardbg}{HTML}{1E293B}         % card background (dark)
\definecolor{cardbg2}{HTML}{1E3A5F}       % alternate card bg
\definecolor{stathighlight}{HTML}{1E3A8A} % stat highlight bg
\definecolor{textwhite}{HTML}{F8FAFC}      % white text
\definecolor{textmuted}{HTML}{94A3B8}      % muted text
\definecolor{aitag}{HTML}{10B981}         % AI tag green
\definecolor{othercolor}{HTML}{64748B}    % non-AI tag gray

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}

% ── Card styles ──
\tcbset{
  card/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardbg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={secondary!60},
    valign=top, drop shadow={opacity=0.3},
  },
  cardgreen/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={accent!60},
    valign=top, drop shadow={opacity=0.3},
  },
  cardamber/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent2},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent2},
    coltitle=accent2, colbacktitle=cardbg,
    toptitle=4pt, bottomtitle=4pt,
    titlerule=2pt, titlerule style={accent2!60},
    valign=top, drop shadow={opacity=0.3},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=stathighlight,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=stathighlight,
    toptitle=4pt, bottomtitle=4pt,
    valign=top, drop shadow={opacity=0.3},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=24, spacing=0mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries GitHub's Hottest Repos}\\[10pt]
  {\fontsize{42}{50}\selectfont\color{accent} AI Agents Dominate the Trending Charts}\\[8pt]
  {\fontsize{28}{34}\selectfont\color{textmuted} Data Report • 24-Hour Trending • OSSInsight}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=stathighlight, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{secondary!50},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent} 10.6B+}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textwhite} GitHub Events Tracked}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{secondary} 70\%}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textwhite} AI/Agent Repos (14/20)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.31\linewidth}\centering
    \fcolorbox{accent2!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{58}{70}\selectfont\bfseries\color{accent2} Python}\\[4pt]
      {\fontsize{24}{30}\selectfont\color{textwhite} Most Common (7 repos)}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ TOP 20 TABLE SECTION ══
\posterbox[
  card, title={Top 20 Trending Repositories (Past 24 Hours)},
  colframe=secondary, boxrule=1pt
]{name=table, column=1, span=3, between=row6 and row18}{
  \fontsize{26}{32}\selectfont
  \rowcolors{1}{cardbg}{cardbg2}
  \renewcommand{\arraystretch}{1.4}
  \begin{tabular}{|p{40pt}|p{280pt}|p{80pt}|p{60pt}|p{50pt}|p{40pt}|p{40pt}|}
    \hline
    \rowcolor{stathighlight}
    \centering{\color{textwhite}\bfseries Rank} & \centering{\color{textwhite}\bfseries Repository} & \centering{\color{textwhite}\bfseries Lang} & \centering{\color{textwhite}\bfseries Stars} & \centering{\color{textwhite}\bfseries Forks} & \centering{\color{textwhite}\bfseries Pushes} & \centering{\color{textwhite}\bfseries PRs} \\
    \hline
    \centering\bfseries\textcolor{accent}{#1} & \texttt{forrestchang/andrej-karpathy-skills} & — & \textcolor{accent}{826} & 79 & 0 & 0 \\
    \rowcolor{cardbg2}
    \centering\bfseries\textcolor{secondary}{#2} & \texttt{NousResearch/hermes-agent} & Python & \textcolor{accent}{468} & 102 & 66 & 61 \\
    \hline
    \centering\bfseries #3 & \texttt{NawfalMotii79/PLFM\_RADAR} & Verilog & 353 & 81 & 5 & 0 \\
    \rowcolor{cardbg2}
    \centering\bfseries\textcolor{accent}{#4} & \texttt{thedotmack/claude-mem} & TypeScript & \textcolor{accent}{335} & 33 & 4 & 0 \\
    \hline
    \centering\bfseries #5 & \texttt{VoltAgent/awesome-design-md} & HTML & 321 & 49 & 0 & 0 \\
    \rowcolor{cardbg2}
    \centering\bfseries #6 & \texttt{JuliusBrussee/caveman} & Python & 237 & 19 & 0 & 3 \\
    \hline
    \centering\bfseries #7 & \texttt{multica-ai/multica} & TypeScript & 139 & 13 & 44 & 10 \\
    \rowcolor{cardbg2}
    \centering\bfseries #8 & \texttt{safishamsi/graphify} & Python & 120 & 13 & 0 & 1 \\
    \hline
    \centering\bfseries #9 & \texttt{jamiepine/voicebox} & TypeScript & 100 & 12 & 8 & 3 \\
    \rowcolor{cardbg2}
    \centering\bfseries #10 & \texttt{lsdefine/GenericAgent} & Python & 101 & 9 & 5 & 2 \\
    \hline
    \centering\bfseries #11 & \texttt{rohitg00/ai-engineering-from-scratch} & Python & 82 & 19 & 0 & 0 \\
    \rowcolor{cardbg2}
    \centering\bfseries #12 & \texttt{EvoMap/evolver} & JavaScript & 95 & 5 & 1 & 1 \\
    \hline
    \centering\bfseries #13 & \texttt{google/magika} & Python & 122 & 7 & 0 & 3 \\
    \rowcolor{cardbg2}
    \centering\bfseries #14 & \texttt{vercel-labs/open-agents} & TypeScript & 84 & 12 & 2 & 12 \\
    \hline
    \centering\bfseries #15 & \texttt{thunderbird/thunderbolt} & TypeScript & 82 & 4 & 7 & 0 \\
    \rowcolor{cardbg2}
    \centering\bfseries #16 & \texttt{alchaincyf/nuwa-skill} & Python & 67 & 17 & 0 & 0 \\
    \hline
    \centering\bfseries #17 & \texttt{BasedHardware/omi} & Dart & 111 & 72 & 9 & 7 \\
    \rowcolor{cardbg2}
    \centering\bfseries #18 & \texttt{farion1231/cc-switch} & Rust & 77 & 6 & 5 & 0 \\
    \hline
    \centering\bfseries #19 & \texttt{SimoneAvogadro/android-re...} & Shell & 77 & 0 & 0 & 0 \\
    \rowcolor{cardbg2}
    \centering\bfseries #20 & \texttt{rtk-ai/rtk} & Rust & 73 & 4 & 2 & 1 \\
    \hline
  \end{tabular}
  \vspace{4pt}
  {\fontsize{22}{28}\selectfont\color{textmuted} Sorted by composite score: Stars + Forks + Activity (pushes, PRs)}
}

% ══ AI DOMINANCE CALLOUT ══
\posterbox[
  highlightcard, title={AI Agents Dominate},
  colframe=accent, boxrule=2pt
]{name=ai-callout, column=1, span=2, between=row18 and row21}{
  \fontsize{34}{42}\selectfont
  \begin{center}
    {\fontsize{64}{76}\selectfont\bfseries\color{accent} 70\%}
    {\fontsize{36}{44}\selectfont\color{textwhite} of top-20 repos are}\\[6pt]
    {\fontsize{42}{50}\selectfont\bfseries\color{accent} AI / Agent / Tooling projects}
  \end{center}
}

% ══ LANGUAGE BREAKDOWN ══
\posterbox[
  cardamber, title={Language Breakdown}
]{name=lang, column=3, between=row18 and row21}{
  \fontsize{28}{34}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \colorbox{accent!30}{\parbox{0.85\linewidth}{\textbf{Python} — 7 repos (35\%)}}
    \item \colorbox{secondary!30}{\parbox{0.85\linewidth}{\textbf{TypeScript} — 5 repos (25\%)}}
    \item \colorbox{accent2!30}{\parbox{0.85\linewidth}{\textbf{Rust} — 2 repos (10\%)}}
    \item \colorbox{textmuted!30}{\parbox{0.85\linewidth}{\textbf{Others} — 6 repos (30\%)}}
  \end{itemize}
}

% ══ KEY THEMES SECTION ══
\posterbox[
  cardgreen, title={Key Themes: AI Agents, Token Optimization & Knowledge Graphs}
]{name=themes, column=1, span=3, between=row21 and row24}{
  \fontsize{30}{38}\selectfont
  \begin{tabular}{p{0.24\linewidth}p{0.24\linewidth}p{0.24\linewidth}p{0.24\linewidth}}
    \begin{itemize}
      \item \textbf{Autonomous Agents} & \textbf{Token Optimization} & \textbf{Memory Management} & \textbf{Skill Distillation}
      \item multica, open-agents, GenericAgent & \colorbox{accent!20}{\parbox{0.9\linewidth}{caveman, rtk (60-90\% reduction)}} & \colorbox{secondary!20}{\parbox{0.9\linewidth}{claude-mem, graphify}} & \colorbox{accent2!20}{\parbox{0.9\linewidth}{karpathy-skills, nuwa-skill}}
    \end{itemize}
  \end{tabular}
  \vspace{4pt}
  {\fontsize{24}{30}\selectfont\color{textmuted} \textbf{Bottom line:} Open-source community is racing to build AI-augmented dev infrastructure}
}

% ══ FOOTER ══
\posterbox[
  enhanced, colback=primary, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=4pt, bottom=4pt,
  halign=center, valign=center
]{name=footer, column=1, span=3, between=row24 and bottom}{
  {\fontsize{22}{28}\selectfont\color{textmuted} Data Source: OSSInsight.io • 10,617,087,149 GitHub events tracked • Generated 2026-04-29}
}

\end{tcbposter}
\end{document}

